1	import { ok, fail } from './result.js';
2	import { getCustomer } from './customers.js';
3	import { getProduct } from './catalogue.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	
6	function isValidDate(dateStr) {
7	  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
8	  if (!m) return false;
9	  const date = new Date(`${dateStr}T00:00:00Z`);
10	  return date instanceof Date && !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === dateStr;
11	}
12	
13	/**
14	 * Calculate the total for a single line (qty * unitPrice).
15	 * @param {{ qty: number, unitPrice: number }}
16	 * @returns {number} total in cents
17	 */
18	export function lineTotal(line) {
19	  return line.qty * line.unitPrice;
20	}
21	
22	/**
23	 * Calculate invoice totals (subtotal and total).
24	 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }}
25	 * @returns {{ subtotal: number, total: number }} in cents
26	 */
27	export function invoiceTotals(invoice) {
28	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
29	  return { subtotal, total: subtotal };
30	}
31	
32	/**
33	 * Create an invoice.
34	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
35	 */
36	export function createInvoice({ customerId, issueDate, lines }) {
37	  const customer = getCustomer(customerId);
38	  if (!customer.ok) return fail('CUSTOMER_NOT_FOUND');
39	
40	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
41	
42	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
43	
44	  const invoiceLines = [];
45	  for (const line of lines) {
46	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
47	
48	    const product = getProduct(line.sku);
49	    if (!product.ok) return fail('UNKNOWN_SKU');
50	
51	    invoiceLines.push({
52	      sku: line.sku,
53	      name: product.value.name,
54	      qty: line.qty,
55	      unitPrice: product.value.unitPrice,
56	      vatRate: product.value.vatRate,
57	    });
58	  }
59	
60	  return ok({
61	    customerId,
62	    issueDate,
63	    status: 'draft',
64	    lines: invoiceLines,
65	  });
66	}
67	
68	/**
69	 * Add a line to an invoice (or increase qty if the SKU already exists).
70	 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
71	 * @param {{ sku: string, qty: number }} line
72	 */
73	export function addLine(invoice, { sku, qty }) {
74	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
75	
76	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
77	
78	  const product = getProduct(sku);
79	  if (!product.ok) return fail('UNKNOWN_SKU');
80	
81	  const newLines = invoice.lines.map((line) => ({ ...line }));
82	  const existingLine = newLines.find((line) => line.sku === sku);
83	
84	  if (existingLine) {
85	    existingLine.qty += qty;
86	  } else {
87	    newLines.push({
88	      sku,
89	      name: product.value.name,
90	      qty,
91	      unitPrice: product.value.unitPrice,
92	      vatRate: product.value.vatRate,
93	    });
94	  }
95	
96	  return ok({
97	    ...invoice,
98	    lines: newLines,
99	  });
100	}
101	
102	/**
103	 * Remove a line from an invoice by SKU.
104	 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
105	 * @param {string} sku
106	 */
107	export function removeLine(invoice, sku) {
108	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
109	
110	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
111	  if (lineIndex === -1) return fail('LINE_NOT_FOUND');
112	
113	  if (invoice.lines.length === 1) return fail('NO_LINES');
114	
115	  const newLines = invoice.lines.filter((line, index) => index !== lineIndex);
