  assert.equal(newInvoice.value.lines[1].qty, 10);
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const newInvoice = addLine(result.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(newInvoice.ok, true);
  assert.equal(newInvoice.value.lines.length, 1);
  assert.equal(newInvoice.value.lines[0].qty, 8);
});

test('addLine validates qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 0 }), {
